/** Klubben bakom en adress-slug, eller null. */
export function klubbAvSlug(slug) {
  if (!slug) return null;
  const k = KLUBBAR[String(slug).toLowerCase()];
  return k ? Object.assign({ slug: String(slug).toLowerCase() }, k) : null;
}

/** Klubben bakom ett klubb-id, eller null. */
export function klubbAvId(id) {
  if (!id) return null;
  const nycklar = Object.keys(KLUBBAR);
  for (let i = 0; i < nycklar.length; i++) {
    if (KLUBBAR[nycklar[i]].id === id) {
      return Object.assign({ slug: nycklar[i] }, KLUBBAR[nycklar[i]]);
    }
  }
  return null;
}
